import itertools

def generate_sequence(sequence, num_numbers):
    A = [int(num) for num in sequence.split(',')]
    for perm in itertools.permutations(A):
        if all(perm[i] + perm[(i+1)%len(perm)] != perm[i+1] for i in range(len(perm))):
            if len(perm[:num_numbers]) == num_numbers:
                return ' '.join(map(str, perm[:num_numbers]))
    return 'Sequence not found.'

sequence = '471,768,340,632,498,355,950,812'
num_numbers = 10

generate_sequence(sequence, num_numbers)
```

