sequence = [272, 363, 777, 319, 382, 263, 377]

def find_next_in_sequence(sequence):
    differences = []
    for i in range(len(sequence) - 1):
        differences.append((sequence[i + 1] - sequence[i]) * 2)

    while len(sequence) < 14:
        possible_values = []
        for diff in differences:
            possible_values.append(sequence[-1] + diff)

        while len(possible_values) > 0:
            # Pick a value that has not been used
            value = min(possible_values, key=lambda x: sequence.count(x))
            possible_values.pop(possible_values.index(value))
            if value not in sequence and value > 0 and len(str(value)) <= 3:
                sequence.append(value)

    return sequence

continuous_sequence = find_next_in_sequence(sequence)

